from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _rounded(numerator, denominator, mode):
    if mode == 'half_up':
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, priority, tax_base, refund, component_one=False):
    cutoff = data.get('cutoff', 10**9)
    chosen = {}
    for position, event in enumerate(data['events']):
        sequence = event.get('sequence', 0)
        if sequence > cutoff:
            continue
        event_id = event.get('id', 'anonymous:' + str(position))
        if priority == 'sequence_first':
            order = (sequence, event.get('revision', 0), position)
        else:
            order = (event.get('revision', 0), position)
        if event_id not in chosen or order > chosen[event_id][0]:
            chosen[event_id] = (order, event)

    balances = dict(data.get('opening', {}))
    mode = data['rounding']
    for _, event in chosen.values():
        if event.get('void', False):
            continue
        raw = event['price'] * event.get('quantity', 1)
        discount = min(10000, max(0, event.get('discount_bp', 0)))
        net = _rounded(raw * (10000 - discount), 10000, mode)
        base = net if tax_base == 'discounted' else raw
        tax = _rounded(base * event.get('tax_bp', 0), 10000, mode)
        total = net + tax
        if refund and event.get('kind') == 'refund':
            total = -total
        key = event.get('account', 'default') + '|' + event.get('currency', 'USD')
        balances[key] = balances.get(key, 0) + total
    return {'balances': balances}


def _make_ledger(priority, tax_base, refund=False):
    return lambda data: _ledger(data, priority, tax_base, refund)


def _component_06():
    def solve(data):
        packages = data['packages']
        names = sorted(packages)
        features = set(data.get('features', []))
        blocked = data.get('blocked', {})
        pins = data.get('pins', {})
        roots = {name: tuple(bounds) for name, bounds in data.get('roots', {}).items()}
        best_vector = None
        best = None

        def active_deps(row):
            return [dep for dep in row.get('deps', [])
                    if not dep.get('feature') or dep['feature'] in features]

        def visit(assignments):
            nonlocal best_vector, best
            requirements = dict(roots)
            edges = {}
            for name, version in assignments.items():
                row = next((r for r in packages[name] if r['version'] == version), None)
                if row is None:
                    return
                deps = active_deps(row)
                edges[name] = [dep['name'] for dep in deps]
                for dep in deps:
                    dep_name = dep['name']
                    low, high = dep['min'], dep['max']
                    if dep_name in requirements:
                        old_low, old_high = requirements[dep_name]
                        requirements[dep_name] = (max(low, old_low), min(high, old_high))
                    else:
                        requirements[dep_name] = (low, high)

            for name, version in assignments.items():
                if name not in requirements:
                    return
                low, high = requirements[name]
                if version < low or version > high:
                    return

            unresolved = []
            for name, (low, high) in requirements.items():
                if low > high:
                    return
                candidates = [row['version'] for row in packages[name]
                              if low <= row['version'] <= high
                              and row['version'] not in blocked.get(name, [])
                              and (name not in pins or row['version'] == pins[name])]
                if not candidates:
                    return
                if name not in assignments:
                    unresolved.append((name, candidates))
            if unresolved:
                name, candidates = min(unresolved, key=lambda item: item[0])
                for version in sorted(candidates):
                    next_assignments = dict(assignments)
                    next_assignments[name] = version
                    visit(next_assignments)
                return

            # The closure is complete. Reject cycles in the installed graph.
            visiting, finished = set(), set()

            def acyclic(name):
                if name in visiting:
                    return False
                if name in finished:
                    return True
                visiting.add(name)
                for dependency in edges.get(name, []):
                    if not acyclic(dependency):
                        return False
                visiting.remove(name)
                finished.add(name)
                return True

            if not all(acyclic(name) for name in assignments):
                return
            vector = tuple(assignments.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best = dict(assignments)

        visit({})
        if best is None:
            return {'error': 'unsatisfiable'}
        return {'versions': best}
    return solve


def _component_07():
    from itertools import combinations

    def solve(data):
        k = data['k']
        blocked = set(data.get('blocked', []))
        mandatory = set(data.get('mandatory', []))
        options = [job for job in data['jobs'] if job['id'] not in blocked]
        quotas = data.get('quotas', {})
        best_ids = None
        best_value = None
        for selection in combinations(options, k):
            ids = tuple(sorted(job['id'] for job in selection))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selection:
                group = job['group']
                counts[group] = counts.get(group, 0) + 1
            if any(not (low <= counts.get(group, 0) <= high)
                   for group, (low, high) in quotas.items()):
                continue
            intervals = sorted((job['start'], job['end']) for job in selection)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            value = sum(job['value'] for job in selection)
            if (best_value is None or value > best_value
                    or (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
        if best_ids is None:
            return {'error': 'impossible'}
        return {'selected': list(best_ids), 'value': best_value}
    return solve


def _component_08():
    import heapq

    def solve(data):
        required = data.get('required', [])
        bits = {node: 1 << index for index, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bits.get(data['source'], 0)
        start_state = (data['source'], initial_mask, data['coupons'])
        distances = {start_state: data['start']}
        queue = [(data['start'], data['source'], initial_mask, data['coupons'])]
        graph = [[] for _ in range(data['n'])]
        for edge in data['edges']:
            graph[edge['u']].append(edge)

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data['target'] and mask == full and remaining == 0:
                return {'arrival': arrival}
            for edge in graph[node]:
                depart = max(arrival, edge['open'])
                if depart >= edge['close']:
                    continue
                duration = edge['duration']
                choices = [(duration, remaining)]
                if remaining:
                    discounted = max(2, duration - edge.get('discount', 0))
                    choices.append((discounted, remaining - 1))
                next_node = edge['v']
                next_mask = mask | bits.get(next_node, 0)
                for travel, next_remaining in choices:
                    next_time = depart + travel
                    if next_time > data['deadline']:
                        continue
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < distances.get(next_state, float('inf')):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask,
                                               next_remaining))
        return {'arrival': None}
    return solve


